// ============================================================
// NeuraWeb — Build MDX article from a Google Sheet row
// Input  : rows read from the "Contenu" sheet (one item per row)
// Output : one item per BLOG row ready to publish, with:
//          { slug, lang, path, mdx, frontmatter, rowId }
// ============================================================

function slugify(str) {
  return String(str)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // strip accents
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

// YAML-safe double-quoted scalar
function yamlStr(v) {
  const s = String(v == null ? '' : v).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  return '"' + s + '"';
}

function parseTags(raw) {
  if (Array.isArray(raw)) return raw.map(t => String(t).trim()).filter(Boolean);
  if (!raw) return [];
  return String(raw).split(/[,;|]/).map(t => t.trim()).filter(Boolean);
}

function parseFaq(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  try { const j = JSON.parse(raw); return Array.isArray(j) ? j : []; }
  catch (e) { return []; }
}

const LANGS = ['fr', 'en', 'es'];
const out = [];

for (const item of $input.all()) {
  const r = item.json;

  // Only publish BLOG rows flagged ready (X / Facebook posts are ignored here)
  const type = String(r.type || '').toLowerCase().trim();
  const status = String(r.status || '').toLowerCase().trim();
  if (type !== 'blog') continue;
  if (status !== 'ready' && status !== 'to_publish' && status !== 'a_publier') continue;

  // --- Validation (mirrors lib/mdx.ts validatePostFrontmatter) ---
  const errors = [];
  if (!r.title)    errors.push('title manquant');
  if (!r.excerpt)  errors.push('excerpt manquant');
  if (!r.category) errors.push('category manquante');
  if (!r.content)  errors.push('content (corps MDX) manquant');
  if (errors.length) {
    out.push({ json: { ok: false, rowId: r.id ?? null, slug: null, errors } });
    continue;
  }

  const lang = LANGS.includes(String(r.lang || '').toLowerCase()) ? String(r.lang).toLowerCase() : 'fr';
  const slug = (r.slug && String(r.slug).trim()) ? slugify(r.slug) : slugify(r.title);
  const date = (r.date && !isNaN(Date.parse(r.date))) ? String(r.date).slice(0, 10)
                                                       : new Date().toISOString().slice(0, 10);
  const tags = parseTags(r.tags);
  const faq  = parseFaq(r.faq);
  const featured = String(r.featured).toLowerCase() === 'true' || r.featured === true;
  const image = (r.image && String(r.image).trim()) ? String(r.image).trim()
                                                     : '/assets/blog/' + slug + '.webp';
  const body = String(r.content).trim();
  const words = body.split(/\s+/).filter(Boolean).length;
  const readTime = Math.max(1, Math.ceil(words / 200)) + ' min';

  // --- Frontmatter (gray-matter compatible YAML) ---
  let fm = '---\n';
  fm += 'title: ' + yamlStr(r.title) + '\n';
  if (r.seo_title || r.seoTitle) fm += 'seoTitle: ' + yamlStr(r.seo_title || r.seoTitle) + '\n';
  fm += 'excerpt: ' + yamlStr(r.excerpt) + '\n';
  fm += 'date: ' + yamlStr(date) + '\n';
  fm += 'readTime: ' + yamlStr(readTime) + '\n';
  fm += 'category: ' + yamlStr(r.category) + '\n';
  fm += 'author: ' + yamlStr(r.author || 'NeuraWeb') + '\n';
  fm += 'image: ' + yamlStr(image) + '\n';
  fm += 'tags:\n';
  for (const t of tags) fm += '  - ' + yamlStr(t) + '\n';
  fm += 'featured: ' + (featured ? 'true' : 'false') + '\n';
  if (faq.length) {
    fm += 'faq:\n';
    for (const f of faq) {
      fm += '  - question: ' + yamlStr(f.question) + '\n';
      fm += '    answer: ' + yamlStr(f.answer) + '\n';
    }
  }
  fm += '---\n\n';

  const mdx = fm + body + '\n';

  // App lives in /project in the repo → blog content path is project/content/blog/<lang>/<slug>.mdx
  // (FR articles live at the root of content/blog, EN/ES in subfolders)
  const path = lang === 'fr'
    ? 'project/content/blog/' + slug + '.mdx'
    : 'project/content/blog/' + lang + '/' + slug + '.mdx';

  out.push({
    json: {
      ok: true,
      rowId: r.id ?? null,
      rowNumber: item.json.row_number ?? null,
      slug, lang, path, readTime, words,
      url: 'https://neuraweb.tech/' + lang + '/blog/' + slug,
      frontmatter: { title: r.title, seoTitle: r.seo_title || r.seoTitle || null, excerpt: r.excerpt, date, category: r.category, author: r.author || 'NeuraWeb', image, tags, featured, faq },
      mdx,
      mdxBase64: Buffer.from(mdx, 'utf8').toString('base64'),
      commitMessage: 'content(blog): publish ' + lang + '/' + slug
    }
  });
}

return out;
